import{_ as a,o as t,c as n,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"EmbSpatial-Bench: Benchmarking Spatial Understanding for Embodied Tasks with Large Vision-Language Models","description":"","frontmatter":{"title":"EmbSpatial-Bench: Benchmarking Spatial Understanding for Embodied Tasks with Large Vision-Language Models","arxiv":"2406.05756","date":"2024-06-09","authors":"Mengfei Du, Binhao Wu, Zejun Li, Xuanjing Huang, Zhongyu Wei","categories":"cs.AI, cs.CL, cs.CV, cs.MM","topics":"具身空间理解, 视觉语言模型评测, 指令微调","outline":[2,2]},"headers":[],"relativePath":"papers/2406.05756.md","filePath":"papers/2406.05756.md","lastUpdated":null}'),p={name:"papers/2406.05756.md"};function l(i,s,r,o,m,h){return t(),n("div",null,[...s[0]||(s[0]=[e('<h1 id="embspatial-bench-benchmarking-spatial-understanding-for-embodied-tasks-with-large-vision-language-models" tabindex="-1">EmbSpatial-Bench: Benchmarking Spatial Understanding for Embodied Tasks with Large Vision-Language Models <a class="header-anchor" href="#embspatial-bench-benchmarking-spatial-understanding-for-embodied-tasks-with-large-vision-language-models" aria-label="Permalink to &quot;EmbSpatial-Bench: Benchmarking Spatial Understanding for Embodied Tasks with Large Vision-Language Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2406.05756" target="_blank" rel="noreferrer">2406.05756</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-06-09</td></tr><tr><td><strong>作者</strong></td><td>Mengfei Du, Binhao Wu, Zejun Li, Xuanjing Huang, Zhongyu Wei</td></tr><tr><td><strong>分类</strong></td><td>cs.AI, cs.CL, cs.CV, cs.MM（ACL 2024 Main）</td></tr><tr><td><strong>一句话</strong></td><td>直接从 MP3D/AI2-THOR/ScanNet 的三维标注自动生成&quot;以观察者为中心&quot;的六类空间关系选择题，暴露 LVLM 在具身场景下的空间理解缺口，并用同一条流水线造出 SFT 数据把它补上。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>LVLM 已经被大量工作当作具身智能体的大脑，但它们到底能不能判断&quot;杯子在冰箱左边还是右边&quot;这件事从未被认真测过。论文指出既有的空间理解基准有两个错位。第一是<strong>视角错位</strong>：VSR 这类基准往往从图像内主体的视角描述关系，而具身智能体必须以自己为坐标原点——&quot;左&quot;指的是智能体的左，不是图中人的左。第二是<strong>场景错位</strong>：既有基准建在 MSCOCO、Visual Genome 这类通用图文数据上，与具身场景关系很弱。</p><p>这个缺口重要，是因为它决定了一类判断的可信度。当一篇论文说&quot;LVLM 具备具身智能潜力&quot;时，它引用的往往是通用 VQA 分数；如果具身空间理解从未被单独测过，那么这个推断就没有支撑。论文要做的就是把这个未知量测出来。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>VSR 是最接近的工作，它系统地考察空间关系，但关系判定往往以图中主体为中心。What&#39;sUp 处理的是数据偏置问题，办法是生成干净无杂物的图像以消除无关物体干扰——这恰好把具身场景里最常见的杂乱与遮挡消掉了。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathrm">S</span><span class="mord"><span class="mord mathrm">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathrm mtight">2D</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></span> 面向的是文生图模型的评测，不是理解侧。三者的共同前提是它们都建在 COCO 或 VG 上。</p><p>另一条线是把 LVLM 架构微调到具身任务上的工作，它们初步显示了 LVLM 作为具身智能的潜力，但既没有评测也没有增强空间理解能力。所以问题不是&quot;前人没考虑空间关系&quot;，而是当时空间关系被当作一个通用视觉理解的子问题来处理，而具身设定所要求的&quot;自我中心 + 真实三维场景&quot;这两条约束在通用图文语料上根本无法满足——你没有相机位姿，也没有深度。这解释了为什么必须换数据源：只有带完整三维标注的具身仿真环境才能同时提供这两样东西。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从当时已有的东西出发：MP3D、ScanNet、AI2-THOR 都提供了物体的三维坐标、相机内外参和深度图，这些标注本来是为导航和房间重排任务准备的。把它们当作评测数据的来源需要一个跳跃——既然有三维坐标和相机参数，就可以把物体投影回图像平面得到二维框，也就同时得到了&quot;这个物体在观察者视野的哪个方位&quot;。</p><p>接着是可靠性的顾虑。用目标检测器抽关系会引入检测误差，而三维标注是人工的，直接从标注推关系可以绕开这一层。方位关系（上下左右）可以由二维框的相对位置定，深度关系（远近）可以由框内平均深度定。为了避免歧义，只保留框完全不重叠的关系三元组。</p><p>最后是格式选择。多选题是当时 LVLM 基准的通行做法，可自动判分。但作者显然意识到多选题会把&quot;会不会答题&quot;混进&quot;会不会看图&quot;，所以同时保留了 likelihood 评测作为对照——这一步的动机在论文里写得很直白：把指令遵循能力从被评测能力里分离出来。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>具身场景的空间标注其实已经躺在仿真器里了，只是从来没人把它当评测数据用。有了相机参数就能把三维物体投影成二维框，于是&quot;从智能体视角看，A 在 B 的哪一侧&quot;这个标签可以零人工地批量产生；剩下的只是过滤与人工核验。而同一条流水线换成训练集切分之后，天然就是一份 SFT 数据。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以一张 MP3D 的客厅视图为例：</p><ol><li><strong>取图</strong>：在 MP3D 测试场景与 ScanNet 验证场景里随机选视点，渲染 RGB-D。AI2-THOR 侧不同——从 ALFRED 的 7 类家务任务、93 个场景中，按 PDDL 标注定位任务执行过程中的关键帧。</li><li><strong>抽关系</strong>：用相机内外参把每个物体的三维坐标投到图像平面得到二维框，只保留框互不重叠的三元组。上下左右由整框位置判定（A 的整个框在 B 左侧才算 A 在 B 左）；远近由框内平均深度判定。六类关系覆盖坐标系的三个维度。</li><li><strong>出题</strong>：上下左右用 5 种模板生成问句，把不相关的关系作为错误选项；远近则聚合该图的关系三元组，问&quot;给定物体中哪个最远/最近&quot;。</li><li><strong>过滤与核验</strong>：先自动剔除框过大或过小的样本并保持关系分布平衡；再逐条人工检查三点——问句涉及的物体在图中能否被唯一清晰识别、目标物体是否确实符合所述关系、负选项是否确实错误。任一不满足即丢弃。</li><li><strong>成品</strong>：3,640 道题、2,181 张图、294 个物体类别、277 个场景。三个数据源各约 1,200 题。</li><li><strong>SFT 侧</strong>：只用 MP3D 的训练切分，造 25K 条空间关系识别样本，另加一项辅助任务——物体定位（以文本形式回答边界框），作为关系识别的基础技能。因为只用了 MP3D，AI2-THOR 与 ScanNet 上的评测仍是零样本。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>论文的形式化只有一处，但它决定了后面的结果该怎么读。给定图像 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span></span></span>、问题 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 个选项 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1em;vertical-align:-0.2587em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8247em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span></span></span></span></span><span class="mclose"><span class="mclose">}</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span></span></span></span>，likelihood 策略的预测是</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">c</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">^</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.698em;vertical-align:-0.8233em;"></span><span class="mop">ar<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.4306em;"><span style="top:-2.304em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7571em;"><span style="top:-2.786em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span></span></span></span></span><span class="mrel mtight">∈</span><span class="mord mathnormal mtight" style="margin-right:0.0715em;">C</span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">max</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8233em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:-0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8747em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size1">)</span></span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 由因果语言模型式的 LVLM 参数化。generation 策略则是从模型的文本输出里抽取选项标号。</p><p>这两者的差别值得展开。generation 要求模型完成一条完整的链路：看图 → 判断 → 理解&quot;请从 A/B/C/D 中选一个&quot;这条指令 → 按格式输出标号。likelihood 只要求前两步，第三步被评测者代劳了。因此两者之差可以粗略读作&quot;格式遵循能力&quot;的贡献。数据完全支持这个读法：MiniGPT-v2 在 generation 下只有 23.93，在 likelihood 下是 43.85，相差近 20 个点，排名从垫底跳到开源第一。反过来，Cheetor 是 24.56 / 32.80，BLIP2 是 37.99 / 35.71（反向），说明两套刻度并不单调一致。</p><p>需要注意论文正文未给出选项数 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span>。若按&quot;用其余关系作为错误选项&quot;推测方位类题目是四选一，则随机基线约 25%——在这个刻度下，generation 评测中的 Cheetor(24.56)、mPlugOwl(24.12)、MiniGPT4(23.54)、MiniGPT-v2(23.93) 都落在随机线附近。这属于<strong>基于证据的推断</strong>，因为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 未被明确声明。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>当前 LVLM 的具身空间理解到什么水平？</strong> 10 个开源模型 + 2 个闭源模型的零样本评测。最好成绩是 Qwen-VL-Max 的 49.11（generation）与 MiniGPT-v2 的 43.85（likelihood），GPT-4V 只有 36.07，而人类是 90.33。附录的 GPT-4V 失败案例显示它同时在物体定位和关系判定两步上出错——第一个案例里它把左上角的时钟定位成了右上角，随后自然选了含&quot;right&quot;的选项。</p><p><strong>能不能补上？</strong> 用 EmbSpatial-SFT 微调 MiniGPT-v2（只训练视觉连接模块与 LLM 的 LoRA）。likelihood 下总体从 43.85 升到 78.10（+34.25），generation 下从 23.93 升到 32.97（+9.04）。两个增益的巨大差距本身是个结论：模型确实学会了判断，但仍然不太会按格式把答案说出来。作者还指出 AI2-THOR 上的提升小于 ScanNet，归因于前者是仿真场景而 MP3D/ScanNet 是真实场景。</p><p><strong>哪部分数据在起作用？</strong> 两个消融。冻结 LLM 只训连接模块（w/o LoRA）后成绩崩回接近微调前（generation 25.11、likelihood 43.76），作者据此推断 LLM 骨干需要学到相应的推理能力，而不只是调整输入的视觉表示——这是全文最有力的一条消融。辅助的物体定位数据（w/o OL）贡献很小：总体只差 0.47（generation）与 0.76（likelihood）；而且在 generation 的 MP3D 域内一栏上，<strong>去掉辅助数据反而更好（34.22 vs 31.64）</strong>，论文未讨论这一反向结果。</p><p><strong>局限</strong>：作者自陈数据全部来自室内场景，可能不适用于室外；且只研究了英语。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：EmbSpatial-Bench 把具身仿真环境里现成的三维标注变成 3,640 道以观察者为中心的空间关系选择题，覆盖上下左右远近六类关系与 294 个物体类别。当前 LVLM 在上面表现很差——最好 49.11%，GPT-4V 只有 36.07%，人类 90.33%。同一条流水线在 MP3D 训练切分上造出 25K 条 SFT 数据后，MiniGPT-v2 的 likelihood 成绩从 43.85 升到 78.10，且在另外两个数据源上是零样本。消融显示必须微调 LLM 骨干（只调视觉连接模块几乎无效），而辅助的物体定位数据贡献不到 1 个点。generation 与 likelihood 两套评测的排名严重不一致，说明分数中混入了大量格式遵循能力。</p><p><strong>3 句话版</strong>：具身空间理解需要自我中心视角与真实三维场景，这两点通用图文基准都给不了，而仿真器的标注可以零人工地给。测出来的结果是 LVLM 远不及人类，且失败同时发生在定位与关系判定两步。用同源数据微调 LLM 骨干可以大幅补上，但只调视觉侧不行。</p><p><strong>1 句话版</strong>：把仿真器里的三维标注变成选择题，第一次量出了 LVLM 与&quot;合格具身智能&quot;之间的空间理解差距。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>由二维投影框的完全分离与框内平均深度所定义的关系标签，等同于具身智能体所需要的空间理解</strong>。整个基准的效度都压在这一条上。</p><p>它为什么可能不成立，有两处具体理由。其一是&quot;框必须完全不重叠&quot;这条过滤规则。它是为了消除歧义引入的，但代价是系统性地排除了遮挡与相互穿插——而遮挡恰恰是具身场景中最常见、也最需要空间推理才能处理的情形。基准里剩下的题目因此偏向&quot;两个物体在画面上彼此分开&quot;这一相对简单的子集。其二是&quot;远近由框内平均深度决定&quot;。对于大件、斜置或部分出画的家具（比如一张伸向镜头的桌子），平均深度与人类直觉的&quot;哪个更近&quot;可能不一致，而这类物体在室内场景中占比不低。</p><p>论文为这条假设提供的证据是人工核验：逐条检查了物体是否可唯一识别、关系是否符合、负选项是否确实错误。这确实排除了标注噪声，但它验证的是&quot;人类能复现该定义&quot;，不是&quot;该定义与下游具身任务相关&quot;。人类 90.33% 的分数同样只说明前者。缺失的证据是任何一条把 benchmark 分数与真实导航/操作成功率联系起来的实验——论文完全没有做，而这正是它的动机所在。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要训练大模型。做两件事。</p><p>第一件是重标注对照：把&quot;远近&quot;这一类题目的真值从&quot;框内平均深度&quot;改成&quot;物体三维中心到相机光心的欧氏距离&quot;（三维标注里现成有），重新判分现有的 12 个模型。若模型排名基本不变且分数波动在几个点内，说明定义选择不影响结论；若排名重排，则基准的分数在很大程度上是定义的产物。</p><p>第二件是下游相关性：取 ALFRED 的一个子集（AI2-THOR 侧的题目本就来自 ALFRED 的关键帧），用微调前后的 MiniGPT-v2 各做一次子目标选择，比较任务成功率。判据要提前定死：若微调后 benchmark 涨 34 个点而 ALFRED 成功率变化在噪声内，则 benchmark 的构念效度存疑；若两者同向且幅度相当，则基准得到支持。</p><p>两件事都只需要公开数据与已发布的 checkpoint。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是构造一个<strong>不理解任何东西的强基线</strong>。具体做法：接一个现成的开放词表检测器（比如 Grounding DINO）加一个单目深度估计器，对每道题定位问句中提到的物体，然后用纯规则判定关系——框心横坐标比大小定左右、纵坐标定上下、深度均值定远近。这个流水线里没有任何&quot;空间理解&quot;，只有检测加算术。</p><p>如果这个基线的分数明显高于 GPT-4V 的 36.07，甚至逼近人类的 90.33，那么该基准测的就是&quot;物体定位准确度 + 一段两行的几何规则&quot;，而不是论文标题里的空间理解。这个反例之所以有力，是因为基准的真值本身就是用同一段几何规则从二维框算出来的——一个能拿到准确框的系统在定义上就应当拿满分。论文的 GPT-4V 失败案例分析实际上指向了同一件事：它把错误归因于&quot;定位错了&quot;，那么改进定位就足以刷分。</p><p>第二条攻击针对评测协议：generation 与 likelihood 的排名可以完全反转（MiniGPT-v2 从垫底到开源第一，BLIP2 则反向），且微调收益在两套刻度下相差 25 个点。这意味着&quot;哪个模型的具身空间理解更好&quot;这个问题在当前协议下没有唯一答案，而论文的主结论（&quot;包括 GPT-4V 在内的 LVLM 都不合格&quot;）恰恰依赖于 generation 这一套——对闭源模型只报了 generation 分数，没有 likelihood 对照。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动的局限</strong>：这个基准是单帧、被动、静态的。但具身空间理解的本质困难不在&quot;从一张图读出关系&quot;，而在&quot;当一张图不足以判断时该怎么办&quot;——被遮挡、被截断、深度歧义。论文用&quot;框不重叠&quot;这条过滤规则把这类情形整体排除了，因此它测出的差距虽然真实，却是最容易的那一档。</p><p><strong>新的 framing</strong>：把空间理解从一个感知问题重新定义为一个<strong>主动信息获取</strong>问题。智能体不该被要求从任意一张图里读出正确答案，而应该被要求判断&quot;当前视角够不够，不够的话往哪走一步最有信息量&quot;。这样评测的对象从&quot;读图准确率&quot;变成&quot;消歧策略的效率&quot;，而后者才是导航与操作里真正被使用的能力。</p><p><strong>可借鉴的相邻领域工具</strong>：主动视觉与最优实验设计里的信息增益准则（选择使后验熵下降最多的动作），以及贝叶斯实验设计中的期望信息增益估计。这些工具正好提供了&quot;该往哪看&quot;的形式化目标。</p><p><strong>第一个实验</strong>：在 AI2-THOR 里把现有题目改造成交互式版本——给模型初始视角与问题，允许它最多执行 3 个动作（左转 / 右转 / 前进），每步返回新图，最后作答。同时保留三个对照：零动作（等价于当前基准）、随机 3 步、以及一个用真值三维信息选出的 oracle 动作序列。三条曲线之间的间距直接给出两个量：主动探索能带来多少收益（随机 vs 零动作），以及模型的动作选择离最优有多远（随机 vs oracle）。若随机 3 步就能大幅超过零动作，说明当前基准的低分主要来自视角不利而非理解能力欠缺；若只有 oracle 有效，说明消歧策略本身才是瓶颈。</p>',51)])])}const d=a(p,[["render",l]]);export{g as __pageData,d as default};
